<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\StoreAvailabilityRequest; use App\Models\Availability; use App\Services\ProviderScheduleService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class ProviderAvailabilityController extends Controller { public function index(Request $request): JsonResponse {$p=$this->provider($request);return response()->json(['data'=>$p->availabilities()->orderBy('day_of_week')->orderBy('start_time')->get()]);} public function store(StoreAvailabilityRequest $request,ProviderScheduleService $service): JsonResponse {$p=$this->provider($request);return response()->json(['data'=>$service->createAvailability($p,$request->validated())],201);} public function destroy(Request $request,Availability $availability,ProviderScheduleService $service): JsonResponse {$p=$this->provider($request);abort_unless($availability->provider_id===$p->id,403);$service->deleteAvailability($availability);return response()->json(['message'=>'Availability deleted.']);} private function provider(Request $request){return $request->user()->provider ?: abort(403,'Provider profile required.');} }
